"""Real HTTP/server browser tests. No physical Android/Windows/TV claim."""
from test_observation_remote import ObservationRemote
class PersonalitiesRemote(ObservationRemote):
 def test_classified_capability_never_leaks_into_paired_views(self):
  pc=self.page(pc=True);pc.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');pc.evaluate('__icarusSoak.advance(1)');pc.wait_for_timeout(1800)
  self.assertEqual(self.req('/api/icarus/classified',headers={'Authorization':'Bearer test-client'})[0],403)
  key=self.req('/api/icarus/bootstrap')[1]['key'];code,data=self.req('/api/icarus/classified',headers={'X-Icarus-Key':key});self.assertEqual(code,200);self.assertEqual(len(data['telemetry']['rooms']),2);self.assertTrue(all(r['id'].startswith('COV-') for r in data['telemetry']['rooms']))
  code,_=self.req('/api/icarus/classified',headers={'X-Icarus-Key':key,'Host':'192.168.1.123'});self.assertEqual(code,403)
  ordinary=self.req('/api/icarus/live',headers={'Authorization':'Bearer test-client'})[1];self.assertNotIn('classified',ordinary['telemetry']);self.assertNotIn('classifiedOps',ordinary['telemetry']);self.assertFalse(any(r.get('classified') for r in ordinary['telemetry']['observation']['rooms']));self.assertFalse(any(r['id'].startswith('COV-') for r in ordinary['telemetry']['observation']['rooms']))
  pc.evaluate("ICARUSCommandUI.navigate('settings','general')");terminal=pc.locator('.classified-terminal');terminal.locator('summary').click();terminal.locator('.classified-unlock').click();pc.wait_for_function('document.querySelector(".classified-status").textContent.includes("CLASSIFIED HOST CONNECTED")');terminal.locator('input').fill('help');terminal.locator('input').press('Enter');self.assertIn('no shell execution',terminal.locator('.classified-command-result').inner_text());terminal.locator('.classified-lock').click();self.assertEqual(terminal.locator('.classified-status').inner_text(),'LOCKED');self.assertFalse(pc.evaluate('ICARUSBridgeMode.creator'))
 def test_paired_follow_and_lift_catalog_do_not_run_another_world(self):
  pc=self.page(pc=True);pc.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');pc.evaluate('__icarusSoak.advance(1)');phone=self.page(width=390,height=844);self.tab(phone,'icarus');phone.wait_for_selector('.obs-follow');phone.locator('.obs-follow').select_option('Frank Morrow');self.assertEqual(phone.evaluate('typeof __icarusSoak'),'undefined');self.assertTrue(any('LIFT-01' in x for x in phone.locator('.obs-select option').all_text_contents()));self.assertLessEqual(phone.evaluate('document.documentElement.scrollWidth'),392);self.assertFalse(any('COV-' in x for x in phone.locator('.obs-select option').all_text_contents()))
